// One realistic source to repurpose, no external services needed.
return [{ json: {
  Tone: 'Professional',
  Brand: 'PERLY',
  Content: `Most small teams lose deals not because their product is weak, but because follow-up is slow and inconsistent. `+
    `When a lead fills in a form, the clock starts: reply within an hour and you are several times more likely to `+
    `connect than if you wait a day. Yet manual follow-up is exactly what gets dropped when everyone is busy. `+
    `The fix is not a bigger CRM — it is a small, reliable automation: capture the lead, validate the email, score `+
    `it by a few transparent rules, and route hot ones to a human immediately while everything is logged. Teams that `+
    `do this recover hours a week and stop letting warm leads go cold. Automation here is not about replacing the `+
    `human touch; it is about making sure the human touch actually happens, on time, every time.`
}}];

// Read the form submission (or the TEST sample) and build the AI input. Iterates all items.
const MAX = 6000;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let content = String(j.Content || j.content || '').trim();
  if (content.length > MAX) content = content.slice(0, MAX) + ' …[truncated]';
  const tone = String(j.Tone || j.tone || 'Professional').trim();
  const brand = String(j.Brand || j.brand || '').trim();
  out.push({ json: {
    content, tone, brand,
    sourcePreview: content.slice(0, 120),
    createdAt: $now.toISO(),
    aiInput: `TONE: ${tone}\nBRAND/VOICE: ${brand || '(none given)'}\n\nSOURCE CONTENT:\n${content}`
  }});
}
return out;

// Honest guardrail: coerce arrays, verify every platform got real content, flag thin output.
// Pairs each AI item with its source by position (extractor emits one item per input, in order).
const preps = $('Prepare content').all();
const items = $input.all();
const asArr = v => Array.isArray(v) ? v : (v ? String(v).split('\n').filter(Boolean) : []);
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;
  const ai = (src && typeof src.output === 'object' && src.output) ? src.output : src;
  const prep = (preps[i] || preps[0] || { json: {} }).json;
  const hook = String(ai.hook || '').trim();
  const linkedin = String(ai.linkedin_post || '').trim();
  const xThread = asArr(ai.x_thread).map(s => String(s).trim()).filter(Boolean);
  const ig = String(ai.instagram_caption || '').trim();
  const news = String(ai.newsletter_blurb || '').trim();
  const tags = asArr(ai.hashtags).map(s => '#' + String(s).trim().replace(/^#+/, '')).filter(t => t.length > 1);
  const takeaway = String(ai.key_takeaway || '').trim();
  const lang = String(ai.detected_language || '').trim();
  const needsReview = !(hook && linkedin && xThread.length >= 2 && news && tags.length >= 1);
  out.push({ json: {
    createdAt: prep.createdAt, brand: prep.brand, tone: prep.tone,
    sourcePreview: prep.sourcePreview, detectedLanguage: lang,
    hook, linkedinPost: linkedin,
    xThread: xThread.join('\n\n'), xThreadCount: xThread.length,
    instagramCaption: ig, newsletterBlurb: news,
    hashtags: tags.join(' '), keyTakeaway: takeaway,
    needsReview, repurposeVersion: 'perly-content-repurposer-v1.0'
  }});
}
return out;

// Tolerant assertions — the model is non-deterministic, so check structure, not exact strings.
const rows=$input.all().map(i=>i.json);
const problems=[];
for(const r of rows){
  if(!r.hook) problems.push('empty hook');
  if(!r.linkedinPost || r.linkedinPost.length<80) problems.push('linkedin post too short');
  if((r.xThreadCount||0)<2) problems.push('x thread has fewer than 2 tweets');
  if(!r.newsletterBlurb) problems.push('no newsletter blurb');
  if(!r.hashtags) problems.push('no hashtags');
  for(const t of String(r.xThread||'').split('\n\n')){ if(t.length>280) problems.push('a tweet exceeds 280 chars'); }
}
// Un test che fallisce deve FALLIRE, non restituire un oggetto triste che nessuno
// legge. Senza questa riga l'esecuzione resta verde e il pannello di n8n dice che
// è andato tutto bene: esattamente il guasto silenzioso contro cui esiste il test.
if (problems.length) {
  throw new Error(`TEST FAILED (${problems.length}): ` + problems.join(' | '));
}
return [{json:{result:problems.length?'FAILED':'PASSED',checked:rows.length,problems,
  sample:{lang:rows[0].detectedLanguage,hook:rows[0].hook,tweets:rows[0].xThreadCount,hashtags:rows[0].hashtags}}}];
